-- Extend the existing flat website CMS. Amenities are validated JSON text, never operational inventory.
begin;
create function public.validate_hero_amenities_v1(p_value text) returns boolean language plpgsql immutable set search_path='' as $$
declare items jsonb; a jsonb; seen text[] := '{}';
begin
 items:=p_value::jsonb;
 if jsonb_typeof(items) is distinct from 'array' or jsonb_array_length(items)>50 then return false; end if;
 for a in select value from jsonb_array_elements(items) loop
  if jsonb_typeof(a) is distinct from 'object' or (select count(*) from jsonb_object_keys(a))<>8 then return false; end if;
  if coalesce(a->>'id','') !~ '^[a-f0-9-]{36}$' or a->>'id'=any(seen) or coalesce(a->>'icon','') not in ('clock','languages','stop','ticket','snowflake','wifi','people','van','map','pin','headphones','camera','info') then return false; end if;
  if jsonb_typeof(a->'title') is distinct from 'string' or length(btrim(a->>'title'))=0 or length(a->>'title')>100 or jsonb_typeof(a->'description') is distinct from 'string' or length(a->>'description')>180 or jsonb_typeof(a->'published') is distinct from 'boolean' or jsonb_typeof(a->'display_order') is distinct from 'number' or (a->>'display_order') !~ '^[0-9]{1,3}$' then return false; end if;
  if jsonb_typeof(a->'created_at') is distinct from 'string' or jsonb_typeof(a->'updated_at') is distinct from 'string' or (a->>'created_at')::timestamptz is null or (a->>'updated_at')::timestamptz is null then return false; end if;
  seen:=array_append(seen,a->>'id');
 end loop;
 return true;
exception when others then return false;
end $$;
revoke all on function public.validate_hero_amenities_v1(text) from public,anon,authenticated;
grant execute on function public.validate_hero_amenities_v1(text) to service_role;

create or replace function public.validate_website_content_v1(p_data jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare spec jsonb := '{"tourPage.eyebrow":{"kind":"text","max":700},"tourPage.includedTitle":{"kind":"text","max":700},"tourPage.faqTitle":{"kind":"text","max":700},"tourPage.faqBook":{"kind":"text","max":700},"tourPage.faqBoard":{"kind":"text","max":700},"tourPage.faqFees":{"kind":"text","max":700},"tourPage.faqLive":{"kind":"text","max":700},"explorePage.eyebrow":{"kind":"text","max":700},"explorePage.title":{"kind":"text","max":700},"explorePage.text":{"kind":"text","max":700},"bookPage.eyebrow":{"kind":"text","max":700},"bookPage.title":{"kind":"text","max":700},"dayPage.eyebrow":{"kind":"text","max":700},"dayPage.title":{"kind":"text","max":700},"hero.eyebrow":{"kind":"text","max":700},"hero.title":{"kind":"text","max":700},"hero.emphasis":{"kind":"text","max":700},"hero.description":{"kind":"text","max":700},"hero.subtitle":{"kind":"text","max":700},"hero.desktop":{"kind":"image","max":2000},"hero.mobile":{"kind":"image","max":2000},"hero.desktopPosition":{"kind":"position","max":2000},"hero.mobilePosition":{"kind":"position","max":2000},"hero.alt":{"kind":"text","max":700},"hero.book":{"kind":"text","max":700},"hero.track":{"kind":"text","max":700},"hero.discover":{"kind":"text","max":700},"hero.amenities":{"kind":"amenities","max":30000},"intro.eyebrow":{"kind":"text","max":700},"intro.title":{"kind":"text","max":700},"intro.text":{"kind":"text","max":700},"intro.linkLabel":{"kind":"text","max":700},"intro.link":{"kind":"link","max":2000},"route.eyebrow":{"kind":"text","max":700},"route.title":{"kind":"text","max":700},"route.text":{"kind":"text","max":700},"destinations.eyebrow":{"kind":"text","max":700},"destinations.title":{"kind":"text","max":700},"place.centre.name":{"kind":"text","max":700},"place.centre.tag":{"kind":"text","max":700},"place.centre.text":{"kind":"text","max":700},"place.centre.detail":{"kind":"text","max":700},"place.centre.image":{"kind":"image","max":2000},"place.centre.alt":{"kind":"text","max":700},"place.centre.link":{"kind":"link","max":2000},"place.castle.name":{"kind":"text","max":700},"place.castle.tag":{"kind":"text","max":700},"place.castle.text":{"kind":"text","max":700},"place.castle.detail":{"kind":"text","max":700},"place.castle.image":{"kind":"image","max":2000},"place.castle.alt":{"kind":"text","max":700},"place.castle.link":{"kind":"link","max":2000},"place.lake.name":{"kind":"text","max":700},"place.lake.tag":{"kind":"text","max":700},"place.lake.text":{"kind":"text","max":700},"place.lake.detail":{"kind":"text","max":700},"place.lake.image":{"kind":"image","max":2000},"place.lake.alt":{"kind":"text","max":700},"place.lake.link":{"kind":"link","max":2000},"place.bridge.name":{"kind":"text","max":700},"place.bridge.tag":{"kind":"text","max":700},"place.bridge.text":{"kind":"text","max":700},"place.bridge.detail":{"kind":"text","max":700},"place.bridge.image":{"kind":"image","max":2000},"place.bridge.alt":{"kind":"text","max":700},"place.bridge.link":{"kind":"link","max":2000},"live.eyebrow":{"kind":"text","max":700},"live.title":{"kind":"text","max":700},"live.emphasis":{"kind":"text","max":700},"live.text":{"kind":"text","max":700},"live.linkLabel":{"kind":"text","max":700},"how.eyebrow":{"kind":"text","max":700},"how.title":{"kind":"text","max":700},"how.0.title":{"kind":"text","max":700},"how.0.text":{"kind":"text","max":700},"how.1.title":{"kind":"text","max":700},"how.1.text":{"kind":"text","max":700},"how.2.title":{"kind":"text","max":700},"how.2.text":{"kind":"text","max":700},"how.3.title":{"kind":"text","max":700},"how.3.text":{"kind":"text","max":700},"departures.eyebrow":{"kind":"text","max":700},"departures.title":{"kind":"text","max":700},"departures.linkLabel":{"kind":"text","max":700},"reviews.eyebrow":{"kind":"text","max":700},"reviews.title":{"kind":"text","max":700},"reviews.text":{"kind":"text","max":700},"reviews.second":{"kind":"text","max":700},"notebook.eyebrow":{"kind":"text","max":700},"notebook.title":{"kind":"text","max":700},"notebook.linkLabel":{"kind":"text","max":700},"notebook.0.tag":{"kind":"text","max":700},"notebook.0.title":{"kind":"text","max":700},"notebook.0.linkLabel":{"kind":"text","max":700},"notebook.1.tag":{"kind":"text","max":700},"notebook.1.title":{"kind":"text","max":700},"notebook.1.linkLabel":{"kind":"text","max":700},"notebook.2.tag":{"kind":"text","max":700},"notebook.2.title":{"kind":"text","max":700},"notebook.2.linkLabel":{"kind":"text","max":700},"final.eyebrow":{"kind":"text","max":700},"final.title":{"kind":"text","max":700},"final.emphasis":{"kind":"text","max":700},"final.book":{"kind":"text","max":700},"final.image":{"kind":"image","max":2000},"final.alt":{"kind":"text","max":700},"nav.home":{"kind":"text","max":700},"nav.0.label":{"kind":"text","max":700},"nav.0.link":{"kind":"link","max":2000},"nav.1.label":{"kind":"text","max":700},"nav.1.link":{"kind":"link","max":2000},"nav.2.label":{"kind":"text","max":700},"nav.2.link":{"kind":"link","max":2000},"nav.3.label":{"kind":"text","max":700},"nav.3.link":{"kind":"link","max":2000},"nav.4.label":{"kind":"text","max":700},"nav.4.link":{"kind":"link","max":2000},"nav.book":{"kind":"text","max":700},"nav.mobileBook":{"kind":"text","max":700},"nav.mobileMap":{"kind":"text","max":700},"footer.line1":{"kind":"text","max":700},"footer.line2":{"kind":"text","max":700},"footer.0.label":{"kind":"text","max":700},"footer.0.link":{"kind":"link","max":2000},"footer.1.label":{"kind":"text","max":700},"footer.1.link":{"kind":"link","max":2000},"footer.2.label":{"kind":"text","max":700},"footer.2.link":{"kind":"link","max":2000},"footer.3.label":{"kind":"text","max":700},"footer.3.link":{"kind":"link","max":2000},"footer.4.label":{"kind":"text","max":700},"footer.4.link":{"kind":"link","max":2000},"footer.5.label":{"kind":"text","max":700},"footer.5.link":{"kind":"link","max":2000},"footer.location":{"kind":"text","max":700},"footer.language":{"kind":"text","max":700},"footer.contact":{"kind":"text","max":700},"seo.title":{"kind":"text","max":700},"seo.description":{"kind":"text","max":700},"seo.image":{"kind":"image","max":2000},"seo.alt":{"kind":"text","max":700}}'::jsonb; k text; v text;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_data)) <> (select count(*) from jsonb_object_keys(spec)) then return false; end if;
 for k in select jsonb_object_keys(spec) loop
  v := p_data->>k;
  if jsonb_typeof(p_data->k) is distinct from 'string' or length(btrim(v))=0 or length(v)>(spec->k->>'max')::integer then return false; end if;
  if spec->k->>'kind'='link' and v !~ '^/($|#(route|booking|destinations)$|(tour|live|explore|book|credits|admin)(#(faq|timetable|centre|castle|lake|bridge))?$|explore/(centre|castle|lake|bridge)$)' then return false; end if;
  if spec->k->>'kind'='image' and v !~ '^/images/[a-zA-Z0-9/_-]+[.](webp|png|jpg|jpeg|avif)$' and v !~ '^https://[a-z0-9-]+[.]supabase[.]co/storage/v1/object/public/website-media/[a-f0-9-]+/[a-f0-9-]+[.](webp|png|jpg|avif)$' then return false; end if;
 end loop;
 if p_data->>'hero.desktopPosition' not in ('left top','center top','right top','left center','center center','right center','left bottom','center bottom','right bottom') or p_data->>'hero.mobilePosition' not in ('left top','center top','right top','left center','center center','right center','left bottom','center bottom','right bottom') then return false; end if;
 if not public.validate_hero_amenities_v1(p_data->>'hero.amenities') then return false; end if;
 return true;
end $$;


update public.content_pages set body=jsonb_set(body,'{content}','{"hero.desktopPosition":"center center","hero.mobilePosition":"center center","hero.amenities":"[]","nav.home":"Home"}'::jsonb || (body->'content')),published_body=case when published_body is null then null else jsonb_set(published_body,'{content}','{"hero.desktopPosition":"center center","hero.mobilePosition":"center center","hero.amenities":"[]","nav.home":"Home"}'::jsonb || (published_body->'content')) end where slug='website-homepage' and body->>'format'='homepage_v1';
update public.content_pages set body=jsonb_set(body,'{content,nav.book}',to_jsonb('Book your day'::text)) where slug='website-homepage' and body->'content'->>'nav.book'='Book now';
update public.content_pages set published_body=jsonb_set(published_body,'{content,nav.book}',to_jsonb('Book your day'::text)) where slug='website-homepage' and published_body->'content'->>'nav.book'='Book now';
commit;
